-- =====================================================================
-- Clothing Shop - MySQL schema & seed data
-- Anh nam tai: src/main/resources/static/images/<loai>/NN.jpg (6 loai, moi loai 10 anh)
-- Chay:  mysql -u root < sql/clothing_shop.sql
-- =====================================================================

CREATE DATABASE IF NOT EXISTS clothing_shop
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE clothing_shop;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS product_images;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------- Bang danh muc -----------------------------------------------------
CREATE TABLE categories (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  slug        VARCHAR(100) NOT NULL UNIQUE,
  parent_id   INT NULL,                       -- NULL = nhom cha; co gia tri = danh muc con
  created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_category_parent FOREIGN KEY (parent_id) REFERENCES categories(id)
) ENGINE=InnoDB;

-- ---------- Bang san pham -----------------------------------------------------
CREATE TABLE products (
  id           INT AUTO_INCREMENT PRIMARY KEY,
  category_id  INT NOT NULL,
  name         VARCHAR(150) NOT NULL,
  slug         VARCHAR(150) NOT NULL UNIQUE,
  description  TEXT,
  price        DECIMAL(12,2) NOT NULL,
  stock        INT NOT NULL DEFAULT 0,
  thumbnail    VARCHAR(255),
  created_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_product_category
    FOREIGN KEY (category_id) REFERENCES categories(id)
) ENGINE=InnoDB;

-- ---------- Bang anh san pham (gallery) --------------------------------------
CREATE TABLE product_images (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  product_id  INT NOT NULL,
  image_path  VARCHAR(255) NOT NULL,
  sort_order  INT NOT NULL DEFAULT 0,
  CONSTRAINT fk_image_product
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  CONSTRAINT uq_product_image UNIQUE (product_id, image_path)
) ENGINE=InnoDB;

-- ---------- Bang nguoi dung (khach hang + admin) ----------------------------
-- Dung CREATE ... IF NOT EXISTS va KHONG drop -> chay lai file khong xoa
-- mat khach hang da dang ky. Mat khau luu duoi dang BCrypt hash (app ma hoa).
CREATE TABLE IF NOT EXISTS users (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  full_name   VARCHAR(150) NOT NULL,
  email       VARCHAR(150) NOT NULL UNIQUE,
  password    VARCHAR(255) NOT NULL,
  phone       VARCHAR(20),
  role        VARCHAR(20)  NOT NULL DEFAULT 'CUSTOMER',
  enabled     BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------- Gio hang (moi user 1 gio, moi dong 1 san pham) -------------------
CREATE TABLE IF NOT EXISTS cart_items (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  user_id     INT NOT NULL,
  product_id  INT NOT NULL,
  size        VARCHAR(10) NULL,             -- kich co da chon (S/M/L/XL)
  quantity    INT NOT NULL DEFAULT 1,
  created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_cart_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT uq_cart_user_product_size UNIQUE (user_id, product_id, size)
) ENGINE=InnoDB;

-- ---------- Don hang ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS orders (
  id             INT AUTO_INCREMENT PRIMARY KEY,
  user_id        INT NOT NULL,
  recipient_name VARCHAR(150) NOT NULL,
  phone          VARCHAR(20)  NOT NULL,
  address        VARCHAR(255) NOT NULL,
  note           VARCHAR(255) NULL,                       -- ghi chu (khong bat buoc)
  payment_method VARCHAR(20)  NOT NULL DEFAULT 'CASH',     -- CASH | BANK
  refund_bank         VARCHAR(100) NULL,                  -- ngan hang nhan hoan tien
  refund_account      VARCHAR(50)  NULL,                  -- so tai khoan nhan hoan tien
  refund_account_name VARCHAR(150) NULL,                  -- chu tai khoan
  total_amount   DECIMAL(12,2) NOT NULL,
  status         VARCHAR(20)  NOT NULL DEFAULT 'PROCESSING',  -- PROCESSING|COMPLETED|REFUNDING|CANCELLED
  created_at     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_order_user FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB;

-- ---------- Chi tiet don hang (snapshot ten + gia luc dat) -------------------
CREATE TABLE IF NOT EXISTS order_items (
  id            INT AUTO_INCREMENT PRIMARY KEY,
  order_id      INT NOT NULL,
  product_id    INT NOT NULL,
  product_name  VARCHAR(150) NOT NULL,
  size          VARCHAR(10) NULL,            -- kich co luc dat (snapshot)
  price         DECIMAL(12,2) NOT NULL,
  quantity      INT NOT NULL,
  CONSTRAINT fk_item_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB;

